@* Displays current theme in the header — works even in static SSR *@
<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0d6efd");">
    @ThemeIcon @(Theme?.Theme.ToString() ?? "Light")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeIcon => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Toggle theme">
    @ThemeIcon
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeIcon => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };

    private async Task CycleTheme()
    {
        var next = Theme?.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
        await ThemeSource.NotifyChangedAsync(
            (Theme ?? new ThemeInfo()) with { Theme = next });
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@selectedTheme"
                    @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@accentColor" @onchange="OnAccentChanged" />
        </div>

        <p class="text-muted mb-0">
            Current: <strong>@selectedTheme</strong> /
            <span style="color: @accentColor;">■ @accentColor</span>
        </p>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme selectedTheme;
    private string accentColor = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            selectedTheme = Theme.Theme;
            accentColor = Theme.AccentColor;
        }
    }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        selectedTheme = Enum.Parse<Theme>(e.Value?.ToString() ?? "Light");
        await PushUpdate();
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? "#0d6efd";
        await PushUpdate();
    }

    private Task PushUpdate() =>
        ThemeSource.NotifyChangedAsync(
            new ThemeInfo { Theme = selectedTheme, AccentColor = accentColor });
}

